@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* The bare trigger, its own <button> (the part adds nz-hit-target only then): at least 24 x 24 px,
     the WCAG 2.2 2.5.8 minimum, so a short label or a lone glyph still meets it beside another
     target (M27). The rule also matches a composed Button or IconButton, which carry nz-hit-target
     themselves; at 32, 40 or 48 px it changes nothing there, and it floors a smaller custom height
     at 24 px. A consumer's own element through `render` carries no nz-hit-target and keeps its
     size. The coarse-pointer 44 px hit area is the nz.base .nz-hit-target rule. */
  .nz-tooltip-trigger.nz-hit-target {
    min-inline-size: 1.5rem;
    min-block-size: 1.5rem;
  }

  .nz-tooltip-popup {
    z-index: var(--nz-z-overlay);
    display: flex;
    align-items: center;
    gap: var(--nz-space-2);
    /* the 20rem cap is the whole tooltip, padding included, with or without a page reset (§8.1) */
    box-sizing: border-box;
    max-inline-size: 20rem;
    padding-block: var(--nz-space-2);
    padding-inline: var(--nz-space-3);
    border-radius: var(--nz-tooltip-radius, var(--nz-radius-sm));
    background: var(--nz-tooltip-bg, var(--nz-bg-surface-raised));
    box-shadow: var(--nz-tooltip-shadow, var(--nz-elevation-3));
    color: var(--nz-tooltip-fg, var(--nz-text-primary));
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
    transform-origin: var(--nz-transform-origin);
    /* opacity on --nz-duration-fade (120 ms when reduced, so the fade survives); the rise on
       --nz-duration-fast and --nz-distance-lift, both 0 when reduced (§13.3) */
    transition:
      opacity var(--nz-duration-fade) var(--nz-easing-enter),
      translate var(--nz-duration-fast) var(--nz-easing-enter);

    &[data-entering] {
      opacity: 0;
    }

    /* it rises toward its trigger: from below when above it, and so on */
    &[data-entering][data-side='top'] {
      translate: 0 var(--nz-distance-lift);
    }

    &[data-entering][data-side='bottom'] {
      translate: 0 calc(-1 * var(--nz-distance-lift));
    }

    &[data-entering][data-side='left'] {
      translate: var(--nz-distance-lift) 0;
    }

    &[data-entering][data-side='right'] {
      translate: calc(-1 * var(--nz-distance-lift)) 0;
    }

    &[data-exiting] {
      opacity: 0;
      transition: opacity var(--nz-duration-fade) var(--nz-easing-exit);
    }
  }

  .nz-tooltip-popup .nz-tooltip-shortcut {
    flex: none;
    padding: 0;
    border: 0;
    background: none;
    color: var(--nz-tooltip-shortcut-fg, var(--nz-text-tertiary));
  }

  @media (forced-colors: active) {
    .nz-tooltip-popup {
      border: 1px solid CanvasText;
    }
  }
}
